  background-color: var(--headerBackground);
  color: var(--headerColor);
  position: absolute;
  top: 0;
  left: 0;
  height: 36px;
  width: 100%;
  text-align: center;
  line-height: 36px;
  border-bottom: 1px solid var(--headerBorder);
}
:host .header-panel mat-icon {
  display: inline-block;
  vertical-align: middle;
}
:host .header-panel span {
  margin-left: 10px;
}
:host .work-panel {
  position: absolute;
  top: 37px;
  left: 0;
  right: 0;
  bottom: 0;
  background-color: var(--workPanelBackground);
  overflow: hidden;
}
:host .container {
  height: 100%;
  overflow-y: auto;
  padding: 18px;
  box-sizing: border-box;
}
:host .intro-panel {
  margin-bottom: 14px;
  padding: 10px 18px;
  border: 1px solid rgba(255, 255, 255, 0.08);
  border-left: 3px solid #3f9cff;
  border-radius: 4px;
  background: #313435;
  color: rgba(255, 255, 255, 0.8);
}
:host .intro-title {
  font-size: 14px;
  line-height: 1.5;
}
:host .cards-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
  gap: 10px;
  align-items: stretch;
}
:host .plugin-card {
  display: flex;
  flex-direction: column;
  min-height: 172px;
  padding: 10px;
  border-radius: 6px;
  border: 1px solid rgba(255, 255, 255, 0.08);
  background: #313435;
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.03), 0 10px 26px rgba(0, 0, 0, 0.16);
  color: rgba(255, 255, 255, 0.92);
}
:host .plugin-card.is-installed {
  border-color: rgba(91, 202, 115, 0.4);
}
:host .plugin-card.is-static {
  opacity: 0.9;
}
:host .card-top {
  display: flex;
  align-items: flex-start;
  gap: 10px;
}
:host .card-icon {
  width: 38px;
  height: 38px;
  border-radius: 10px;
  display: flex;
  align-items: center;
  justify-content: center;
  background-color: rgba(255, 255, 255, 0.08);
  color: #7ec4ff;
  flex: 0 0 38px;
}
:host .card-icon mat-icon {
  transform: scale(0.95);
}
:host .card-headline {
  flex: 1;
  min-width: 0;
}
:host .card-type {
  font-size: 11px;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: rgba(255, 255, 255, 0.55);
  margin-bottom: 4px;
}
:host .card-name {
  font-size: 16px;
  font-weight: 600;
  line-height: 1.25;
  word-break: break-word;
}
:host .state-badge {
  width: 30px;
  height: 30px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  flex: 0 0 30px;
  background-color: rgba(255, 255, 255, 0.08);
}
:host .state-badge.ready {
  color: #5bca73;
  background-color: rgba(91, 202, 115, 0.14);
}
:host .state-badge.available {
  color: #f7bf53;
  background-color: rgba(247, 191, 83, 0.14);
}
:host .card-group {
  margin-top: 8px;
  margin-bottom: 8px;
  color: rgba(255, 255, 255, 0.74);
  font-size: 12px;
  min-height: 16px;
}
:host .card-versions {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 8px;
  margin-bottom: 8px;
}
:host .version-box {
  padding: 4px 8px;
  border-radius: 8px;
  background-color: rgba(0, 0, 0, 0.14);
  border: 1px solid rgba(255, 255, 255, 0.05);
}
:host .current-box {
  border-color: rgba(63, 156, 255, 0.22);
}
:host .version-label {
  display: block;
  margin-bottom: 2px;
  font-size: 11px;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: rgba(255, 255, 255, 0.5);
}
:host .version-value {
  display: block;
  font-size: 12px;
  font-weight: 600;
  word-break: break-word;
}
:host .card-status {
  min-height: 14px;
  margin-bottom: 8px;
  color: rgba(255, 255, 255, 0.72);
  font-size: 11px;
  word-break: break-word;
}
:host .card-actions {
  margin-top: auto;
  display: flex;
  align-items: center;
  gap: 8px;
}
:host .action-spinner {
  width: 28px;
  display: flex;
  justify-content: center;
  flex: 0 0 28px;
}
:host .action-button {
  flex: 1;
  min-width: 0;
}
:host .action-button mat-icon {
  margin-right: 6px;
}
:host .action-button[disabled] {
  color: rgba(255, 255, 255, 0.32) !important;
  border-color: rgba(255, 255, 255, 0.12) !important;
  background-color: rgba(255, 255, 255, 0.03) !important;
  box-shadow: none;
  cursor: default;
}
:host .action-button[disabled] mat-icon,
:host .action-button[disabled] span {
  color: rgba(255, 255, 255, 0.32) !important;
}
:host .remove-button {
  color: rgba(255, 255, 255, 0.82);
}
:host .empty-state {
  min-height: 240px;
  border: 1px dashed rgba(255, 255, 255, 0.12);
  border-radius: 14px;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 10px;
  color: rgba(255, 255, 255, 0.52);
}
:host .empty-state mat-icon {
  transform: scale(1.3);
}
