  :host .container {
    padding: 12px;
  }
  :host .cards-grid {
    grid-template-columns: 1fr;
    gap: 12px;
  }
  :host .plugin-card {
    min-height: 0;
    padding: 10px;
  }
  :host .card-versions {
    grid-template-columns: 1fr;
  }
  :host .card-actions {
    flex-wrap: wrap;
  }
  :host .action-spinner {
    width: 100%;
    justify-content: flex-start;
  }
