.scada .sc-table td:first-child { padding-left: 16px; }

.scada .sc-table th:last-child,
.scada .sc-table td:last-child { padding-right: 16px; }

/* camera preview column keeps a stable 16:9 stage */
.cam-preview {
    display: flex;
    flex-direction: column;
    gap: 10px;
}

.cam-preview app-camera-view {
    display: block;
    width: 100%;
}

.scada .sc-table tr.sc-clickable.is-selected td {
    background: rgba(61, 155, 255, 0.10);
    color: var(--sc-ink);
}

.scada .row-actions {
    display: inline-flex;
    gap: 4px;
    justify-content: flex-end;
}

.scada .cam-vendor {
    font-size: 11px;
    color: var(--sc-ink-3);
}

@media (max-width: 1100px) {
    .cam-preview { order: -1; }
}

@media (prefers-reduced-motion: reduce) {
    .scada .sc-table tbody tr { transition: none; }
}
